const want="29ad673946f1cf2fb7ee1aea184a9efc1ec00fdca9efc528faf4af8d197915f1";
const H=[["x-gw-key-id","gw-prod-02"],["x-gw-date","2025-11-20T16:02:41Z"],["host","gw.example.com"],["content-type","application/json"]];
const sets={all:n=>true,gw:n=>n.startsWith("x-gw-"),gwct:n=>n.startsWith("x-gw-")||n=="content-type"};
const queries=["tag=%7E&tag=z&verbose=","tag=%7E&tag=z&verbose","tag=%7e&tag=z&verbose=","tag=%7E&tag=z&verbose"];
for(const [sn,f] of Object.entries(sets))for(const q of queries)for(const body of ["UNSIGNED",c.createHash('sha256').update('').digest('hex')])for(const sep of [";",","])for(const t of ["","\n"]){
const h=H.filter(([n])=>f(n)).sort((a,b)=>a[0]<b[0]?-1:1);
const s=["GET","/v2/ledger/export",q,h.map(([n,v])=>n+":"+v).join("\n"),h.map(x=>x[0]).join(sep),body].join("\n")+t;
if(c.createHmac('sha256',key).update(s).digest('hex')==want)console.log("MATCH",sn,q,body.slice(0,8),sep,JSON.stringify(t));}
EOF
node /tmp/v.js

